text:
{
  "kcs": [
    {
      "canonical_name": "数列极限",
      "aliases": ["Sequence Limit"],
      "description": "数列当项数无穷大时趋近的确定值。"
    },
    {
      "canonical_name": "函数极限",
      "aliases": ["Function Limit"],
      "description": "自变量趋于某点时函数值的趋势。"
    },
    {
      "canonical_name": "两个重要极限",
      "aliases": ["Two Important Limits"],
      "description": "sinx/x和(1+1/x)^x的标准极限。"
    },
    {
      "canonical_name": "无穷小量比较与等价无穷小",
      "aliases": ["Infinitesimal Comparison", "等价无穷小"],
      "description": "比较无穷小趋近零的速度，等价替换求极限。"
    },
    {
      "canonical_name": "连续函数",
      "aliases": ["Continuous Function"],
      "description": "极限等于函数值，描述函数光滑变化。"
    },
    {
      "canonical_name": "间断点",
      "aliases": ["Discontinuity"],
      "description": "函数不连续的点，分两类。"
    },
    {
      "canonical_name": "闭区间上连续函数的性质",
      "aliases": ["Properties of Continuous Functions on Closed Intervals", "最值定理", "介值定理", "零点定理"],
      "description": "最值、有界、介值、零点定理。"
    },
    {
      "canonical_name": "导数",
      "aliases": ["Derivative", "导数的定义", "导数的几何意义"],
      "description": "函数变化率极限，几何为切线斜率。"
    },
    {
      "canonical_name": "基本初等函数导数表",
      "aliases": ["Derivatives of Elementary Functions", "导数表"],
      "description": "幂、三角、指数等导数公式。"
    },
    {
      "canonical_name": "求导法则",
      "aliases": ["Differentiation Rules", "四则运算法则", "链式法则", "链式求导", "Chain Rule"],
      "description": "四则、复合、反函数求导规则。"
    },
    {
      "canonical_name": "高阶导数",
      "aliases": ["Higher-Order Derivatives"],
      "description": "导数的导数，高阶变化率。"
    },
    {
      "canonical_name": "莱布尼茨公式",
      "aliases": ["Leibniz Rule", "莱布尼茨法则"],
      "description": "乘积函数的高阶导数公式。"
    },
    {
      "canonical_name": "隐函数求导",
      "aliases": ["Implicit Differentiation"],
      "description": "对隐式方程两边求导解导数。"
    },
    {
      "canonical_name": "罗尔定理",
      "aliases": ["Rolle's Theorem"],
      "description": "两端等值必有内点导数为0。"
    },
    {
      "canonical_name": "拉格朗日中值定理",
      "aliases": ["Lagrange's Mean Value Theorem"],
      "description": "存在点使切线斜率等于弦斜率。"
    },
    {
      "canonical_name": "柯西中值定理",
      "aliases": ["Cauchy's Mean Value Theorem"],
      "description": "拉格朗日中值定理的参数形式。"
    },
    {
      "canonical_name": "洛必达法则",
      "aliases": ["L'Hôpital's Rule"],
      "description": "0/0或∞/∞型极限分子分母分别求导。"
    },
    {
      "canonical_name": "泰勒公式",
      "aliases": ["Taylor's Formula", "泰勒展开", "Taylor Expansion", "泰勒多项式"],
      "description": "多项式逼近函数带余项。"
    },
    {
      "canonical_name": "麦克劳林展开",
      "aliases": ["Maclaurin Expansion", "Maclaurin公式"],
      "description": "泰勒公式在x=0处的展开。"
    },
    {
      "canonical_name": "不定积分",
      "aliases": ["Indefinite Integral", "原函数", "Antiderivative"],
      "description": "导数的逆运算，原函数族加C。"
    },
    {
      "canonical_name": "基本积分表",
      "aliases": ["Basic Integration Formulas"],
      "description": "常见函数的不定积分公式。"
    },
    {
      "canonical_name": "换元积分法",
      "aliases": ["Integration by Substitution", "凑微分法"],
      "description": "变量替换简化积分。"
    },
    {
      "canonical_name": "分部积分法",
      "aliases": ["Integration by Parts"],
      "description": "乘积积分方法。"
    },
    {
      "canonical_name": "定积分",
      "aliases": ["Definite Integral"],
      "description": "积分和的极限，表示累积量。"
    },
    {
      "canonical_name": "牛顿-莱布尼茨公式",
      "aliases": ["Newton-Leibniz Formula", "微积分基本定理"],
      "description": "定积分等于原函数端点差。"
    },
    {
      "canonical_name": "定积分的应用",
      "aliases": ["Applications of Definite Integral"],
      "description": "计算面积、体积、弧长等。"
    }
  ],
